//! CONF-116 (spec §9.4.3 columns 2-3 / §9.4.7, ADR-057 §2.6 and §4 limb
//! (f)): **the ts prerequisite resolves a gap inside one second.** The
//! trace is generated by a real `serve` whose clock carries the
//! millisecond §6 documents (the §2.6 repair, commit `9731e69` — the
//! base tree, where every `ts` ends `.000Z`, is red by construction),
//! so a session driven in quick succession has resolvable `gap_ms` on
//! every step after the first — and `start` carries a non-zero
//! millisecond fraction. A **vintage** record (`.000Z`, the pre-repair
//! writer) still parses; two identical vintage stamps make the gap
//! honestly null (never `0`), and two different ones resolve it.
//!
//! The vintage arms below are DERIVED from the generated trace (a copy
//! with two `ts` values rewritten), not a hand-written fixture — the
//! record's every other byte is the writer's own.

#![forbid(unsafe_code)]

mod common;

use common::{run_steps_session, STEPS_SESSION};

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn conf_116_the_ts_prerequisite_resolves_small_gaps() {
    let (config_path, _records) = common::run_steps_session("conf116", false).await;
    let st = vadis_cli::steps::load_session(&config_path.to_string_lossy(), STEPS_SESSION)
        .expect("the session loads");
    let rep = vadis_cli::steps::reduce(&st).expect("the reducer runs");

    // (f) live half — the repaired clock: at least one row carries a
    // non-zero fraction (the base tree, where 8,260 of 8,260 records
    // ended `.000Z`, is red here), and every step after the first has a
    // RESOLVED gap: the requests were sequential, so each start follows
    // the previous end and the gap is a real, positive measurement.
    assert!(
        rep.rows.iter().any(|r| !r.start.ends_with(".000Z")),
        "the repaired clock writes the fraction §6 documents"
    );
    assert_eq!(rep.rows[0].gap_ms, None, "step 1 has no previous start");
    for row in &rep.rows[1..] {
        let gap = row.gap_ms.expect(
            "steps issued in quick succession are still resolvable — \
             identical ts, and only identical ts, are the hole",
        );
        // `>= 0`, not `> 0`: the gap is the idle time between the
        // previous request's end and this one's start, quantized to
        // whole milliseconds — a sequential pair can land inside one
        // millisecond and honestly read 0. Resolvable is the claim;
        // positivity is not.
        assert!(
            gap >= 0,
            "sequential driving bounds the gap below by 0; got {gap}"
        );
    }

    // (f) vintage half — a `.000Z` record still parses and the gap rule
    // reads it honestly: two identical stamps are unresolvable (null,
    // never 0); two different stamps resolve, even at second precision.
    let vintage = |mut records: Vec<serde_json::Value>, ts0: &str, ts1: &str| {
        records[0]["ts"] = serde_json::json!(ts0);
        records[1]["ts"] = serde_json::json!(ts1);
        let s = vadis_cli::steps::SessionTrace {
            records,
            files_read: 1,
            plan_providers: st.plan_providers.clone(),
            trace_dir: st.trace_dir.clone(),
        };
        vadis_cli::steps::reduce(&s).expect("a vintage record reduces")
    };

    let same_second = vintage(
        st.records.clone(),
        "2026-01-01T00:00:00.000Z",
        "2026-01-01T00:00:00.000Z",
    );
    assert_eq!(
        same_second.rows[1].gap_ms, None,
        "identical ts: the truth is unknown, not zero (§9.4.3)"
    );

    let apart = vintage(
        st.records.clone(),
        "2026-01-01T00:00:00.000Z",
        "2026-01-01T00:00:01.000Z",
    );
    assert!(
        apart.rows[1].gap_ms.is_some(),
        "a resolvable vintage pair resolves — second precision is still precision"
    );
}
